from collections import deque
def tree(values):
    """Build a tree from values listed level by level, None for a missing child: [3, 5, 1, 6, 2, 0, 8]."""
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = deque([root])
    position = 1
    while queue and position < len(values):
        node = queue.popleft()
        for side in ("left", "right"):
            if position < len(values) and values[position] is not None:
                child = TreeNode(values[position])
                setattr(node, side, child)
                queue.append(child)
            position += 1
    return root
def find(root, value):
    """The first node holding this value (the trees below have distinct values)."""
    stack = [root]
    while stack:
        node = stack.pop()
        if node is not None:
            if node.val == value:
                return node
            stack.append(node.right)
            stack.append(node.left)
    raise ValueError(f"{value} is not in the tree")
def ancestor_value(root, p_value, q_value):
    """Ask for the lowest common ancestor of the nodes holding p_value and q_value, and return the value of the node you get back."""
    got = lowest_common_ancestor(root, find(root, p_value), find(root, q_value))
    if not isinstance(got, TreeNode):
        raise AssertionError(f"expected a node of the tree, got {got!r}")
    if find(root, got.val) is not got:
        raise AssertionError("got a node that is not part of the tree: return the node itself, not a copy")
    return got.val
def path_to(root, target):
    """Where target is, written as the attributes to follow from the root: "root", "root.left", "root.left.right", ..."""
    stack = [(root, "root")]
    while stack:
        node, path = stack.pop()
        if node is not None:
            if node is target:
                return path
            stack.append((node.right, path + ".right"))
            stack.append((node.left, path + ".left"))
    return "None" if target is None else "a node that is not in the tree"
def heap_ancestor(a, b):
    """In a full tree numbered 1, 2, 3, ... level by level, the parent of n is n // 2."""
    while a != b:
        if a > b:
